-- ============================================================
-- MIGRACION INCREMENTAL: Texto pegado.txt -> meridian_capacitaciones
-- Generado para aplicarse SOBRE la base existente.
-- No elimina tablas ni datos existentes.
-- MariaDB 10.11+
-- ============================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

-- 1. Ajustes de compatibilidad de estructura
-- El TXT usa permisos.modulo y la base destino no lo contiene.
ALTER TABLE `permisos`
  ADD COLUMN IF NOT EXISTS `modulo` varchar(40) NOT NULL DEFAULT '' AFTER `codigo`;

-- Ampliaciones no destructivas necesarias para aceptar el contenido de auditoria del TXT.
ALTER TABLE `auditoria`
  MODIFY COLUMN `usuario_nombre` varchar(150) DEFAULT NULL,
  MODIFY COLUMN `entidad_id` bigint(20) UNSIGNED DEFAULT NULL;

-- Tablas presentes en el TXT y ausentes en el SQL destino.
CREATE TABLE IF NOT EXISTS `schema_migrations` (
  `migration` varchar(180) NOT NULL,
  `applied_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`migration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `usuario_accesos` (
  `usuario_id_ext` int(10) UNSIGNED NOT NULL COMMENT 'meridian_personal.usuarios_sistema.usuario_id',
  `intentos_fallidos` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `bloqueado_hasta` datetime DEFAULT NULL,
  `ultimo_acceso` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`usuario_id_ext`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `usuario_roles` (
  `usuario_role_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `usuario_id_ext` int(10) UNSIGNED NOT NULL COMMENT 'meridian_personal.usuarios_sistema.usuario_id',
  `role_id` int(10) UNSIGNED NOT NULL,
  `asignado_por_usuario_id_ext` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`usuario_role_id`),
  UNIQUE KEY `uq_usuario_roles` (`usuario_id_ext`,`role_id`),
  KEY `ix_usuario_roles_rol` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

