-- 3. Vista presente en el TXT y ausente en el SQL destino.
-- Se omite DEFINER=root@localhost para evitar errores de privilegios en cPanel/hosting.
CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `vw_asignaciones_seguimiento` AS
SELECT
  `a`.`asignacion_id` AS `asignacion_id`,
  `a`.`persona_id_ext` AS `persona_id_ext`,
  `a`.`contrato_id_ext` AS `contrato_id_ext`,
  `a`.`capacitacion_id` AS `capacitacion_id`,
  `a`.`cargo_id_ext` AS `cargo_id_ext`,
  `a`.`area_id` AS `area_id`,
  `a`.`proceso_id` AS `proceso_id`,
  `a`.`ambito` AS `ambito`,
  `a`.`proyecto` AS `proyecto`,
  `a`.`origen` AS `origen`,
  `a`.`fecha_asignacion` AS `fecha_asignacion`,
  `a`.`fecha_limite_cumplimiento` AS `fecha_limite_cumplimiento`,
  `cap`.`codigo` AS `capacitacion_codigo`,
  `cap`.`nombre` AS `capacitacion_nombre`,
  `cap`.`es_tarea_critica` AS `es_tarea_critica`,
  `cap`.`criticidad` AS `criticidad`,
  `cap`.`tipo_capacitacion_id` AS `tipo_capacitacion_id`,
  `cap`.`duracion_estimada_horas` AS `duracion_estimada_horas`,
  `c`.`cumplimiento_id` AS `cumplimiento_id`,
  `c`.`fecha_realizacion` AS `fecha_realizacion`,
  `c`.`fecha_vencimiento` AS `fecha_vencimiento`,
  `c`.`horas_efectivas` AS `horas_efectivas`,
  `c`.`nota_evaluacion` AS `nota_evaluacion`,
  `c`.`resultado` AS `resultado`,
  (`c`.`cumplimiento_id` IS NOT NULL) AS `tiene_cumplimiento`,
  CASE
    WHEN `c`.`cumplimiento_id` IS NULL THEN `a`.`fecha_limite_cumplimiento`
    ELSE `c`.`fecha_vencimiento`
  END AS `fecha_control`,
  TO_DAYS(CASE
    WHEN `c`.`cumplimiento_id` IS NULL THEN `a`.`fecha_limite_cumplimiento`
    ELSE `c`.`fecha_vencimiento`
  END) - TO_DAYS(CURDATE()) AS `dias_restantes`
FROM `asignaciones_capacitacion` `a`
JOIN `capacitaciones` `cap`
  ON `cap`.`capacitacion_id` = `a`.`capacitacion_id`
LEFT JOIN `cumplimientos_capacitacion` `c`
  ON `c`.`asignacion_id` = `a`.`asignacion_id`;

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;

